function abilityPoolFor(pathKey){return pathKey==='gryphon'?FLIER_GIFTS:RIDER_SIGNETS;}
function abilityLabelFor(pathKey){return pathKey==='gryphon'?'Gryphon Gift':pathKey==='dark'?'Dark Manifestation':'Signet';}
function darkEffectFor(ability){return DARK_ABILITY_EFFECTS[ability.id]||DARK_CATEGORY_EFFECTS[ability.category]||'The source amplifies the signet beyond its natural limits and makes restraint increasingly difficult.';}
function abilityBySavedValue(value,pathKey='rider'){
  const raw=typeof value==='object'?(value.abilityId||value.id||value.name):value,modern=LEGACY_ABILITY_NAMES[raw]||raw;
  return abilityPoolFor(pathKey).find(item=>item.id===modern||item.name===modern)||null;
}
function legacyAbility(value,description=''){
  const name=typeof value==='object'?(value.name||value.ability||value.id):String(value||'Legacy Ability');
  return {id:`legacy-${name.toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'')}`,name,description:description||LEGACY_ABILITY_DESCRIPTIONS[name]||'A preserved legacy ability from an earlier service record.',traits:['legacy'],category:'Legacy',legacy:true};
}
function selectAbility(pool,scores={}){
  return pool.map((ability,index)=>({ability,index,score:ability.traits.reduce((sum,trait,traitIndex)=>sum+(Number(scores[trait])||0)*(traitIndex?0.72:1),0)}))
    .sort((a,b)=>b.score-a.score||a.index-b.index)[0].ability;
}


