function loadState(){
  const raw=localStorage.getItem(STORAGE_KEY); if(raw){try{return normalizeState(JSON.parse(raw));}catch(e){}}
  const legacy=localStorage.getItem(LEGACY_KEY); if(legacy){try{return migrateLegacy(JSON.parse(legacy));}catch(e){}}
  return freshState();
}
function normalizeBondAbility(bond,pathKey){
  if(!bond)return bond;
  const saved=bond.abilityId||bond.ability,ability=abilityBySavedValue(saved,pathKey)||legacyAbility(bond.ability||saved,bond.abilityDesc);
  bond.abilityId=ability.id;bond.ability=ability.name;bond.abilityDesc=ability.description;bond.abilityCategory=ability.category;
  if(pathKey==='dark')bond.darkEffect=darkEffectFor(ability);else delete bond.darkEffect;
  return bond;
}
function normalizeTextList(values){const source=Array.isArray(values)?values:String(values||'').split(',');const seen=new Map();source.forEach(value=>{const display=String(value||'').trim().replace(/\s+/g,' '),key=display.toLocaleLowerCase();if(display&&!seen.has(key))seen.set(key,display);});return [...seen.values()];}
