function libraryVisibilityControls(visible){const labels={cover:'Cover image',author:'Author',series:'Series',status:'Status',progress:'Progress',rating:'Overall rating',spice:'Spice rating',impact:'Emotional impact',reaction:'Reaction',actions:'Action buttons'};return Object.entries(labels).map(([key,label])=>`<label class="library-visibility-toggle"><input type="checkbox" data-library-visible="${key}" ${visible[key]!==false?'checked':''}><span>${label}</span></label>`).join('');}
function renderLibrary(){const el=document.getElementById('library'),prefs=state.libraryPreferences,desktop=matchMedia('(min-width:651px)').matches,open=desktop||libraryFiltersOpen;el.dataset.libraryLayout=prefs.layout;el.dataset.cardSize=prefs.cardSize;el.innerHTML=`<div class="library-mobile-header"><button class="primary-button library-add" data-action="add-book">${copy('addBook')}</button></div><details class="library-preferences" id="libraryPreferences" ${open?'open':''}><summary aria-expanded="${open}" aria-controls="libraryPreferenceControls">Library View & Filters</summary><div class="library-controls" id="libraryPreferenceControls" aria-label="Library controls"><label class="library-control library-search"><span>Search</span><input class="search-input" id="bookSearch" value="${esc(librarySearchQuery)}" placeholder="Titles, authors, or series"></label><label class="library-control"><span>Organize by</span><select class="select-input" id="bookSort">${[['added','Recently Added'],['updated','Recently Updated'],['title','Title A–Z'],['title-desc','Title Z–A'],['author','Author A–Z'],['series-order','Series Order'],['rating','Highest Rated'],['rating-low','Lowest Rated'],['impact','Highest Emotional Impact'],['spice','Highest Spice'],['progress','Completion Percentage'],['started','Date Started'],['completed-date','Date Completed']].map(([value,label])=>`<option value="${value}" ${prefs.sort===value?'selected':''}>${label}</option>`).join('')}</select></label><label class="library-control"><span>Group by</span><select class="select-input" id="bookGroup">${[['none','None'],['series','Series'],['author','Author'],['status','Status'],['genre','Genre'],['rating','Rating'],['year','Reading Year'],['favorites','Favorites'],['reading','Currently Reading'],['completed','Completed']].map(([value,label])=>`<option value="${value}" ${prefs.group===value?'selected':''}>${label}</option>`).join('')}</select></label><label class="library-control"><span>Genre</span><select class="select-input" id="bookGenre"><option value="">All genres</option>${[...new Set(state.books.flatMap(book=>book.genres||[]))].sort().map(genre=>`<option ${prefs.genre===genre?'selected':''}>${esc(genre)}</option>`).join('')}</select></label><label class="library-control"><span>Layout</span><select class="select-input" id="bookLayout"><option value="list" ${prefs.layout==='list'?'selected':''}>List</option><option value="cards" ${prefs.layout==='cards'?'selected':''}>Cards</option></select></label><label class="library-control"><span>Card size</span><select class="select-input" id="bookCardSize">${['small','medium','large'].map(value=>`<option value="${value}" ${prefs.cardSize===value?'selected':''}>${value[0].toUpperCase()+value.slice(1)}</option>`).join('')}</select></label><fieldset class="library-display-options"><legend>Choose what appears</legend><div class="library-visibility-grid">${libraryVisibilityControls(prefs.visible)}</div></fieldset></div></details><div class="panel library-book-list" id="bookList"></div>`;const list=el.querySelector('#bookList'),search=el.querySelector('#bookSearch');const draw=()=>{const q=search.value.toLowerCase(),sort=prefs.sort;const books=state.books.filter(book=>!book.removedFromLibrary).filter(book=>`${book.title} ${book.author||''} ${book.series||''} ${(book.genres||[]).join(' ')}`.toLowerCase().includes(q)&&(prefs.genre===''||(book.genres||[]).includes(prefs.genre)));const dateValue=(book,key)=>Number(new Date(book[key]||0))||0;if(sort==='added')books.sort((a,b)=>dateValue(b,'createdAt')-dateValue(a,'createdAt'));if(sort==='updated')books.sort((a,b)=>dateValue(b,'updatedAt')-dateValue(a,'updatedAt'));if(sort==='title'||sort==='title-desc')books.sort((a,b)=>String(a.title).localeCompare(String(b.title))*(sort==='title-desc'?-1:1));if(sort==='author')books.sort((a,b)=>String(a.author||'').localeCompare(String(b.author||'')));if(sort==='series-order')books.sort((a,b)=>String(a.series||'').localeCompare(String(b.series||''))||(Number(a.seriesOrder)||0)-(Number(b.seriesOrder)||0));if(sort==='rating'||sort==='rating-low')books.sort((a,b)=>((Number(b.rating)||0)-(Number(a.rating)||0))*(sort==='rating-low'?-1:1));if(sort==='impact')books.sort((a,b)=>(Number(b.impact)||0)-(Number(a.impact)||0));if(sort==='spice')books.sort((a,b)=>(Number(b.spice)||0)-(Number(a.spice)||0));if(sort==='progress')books.sort((a,b)=>(Number(b.progress)||0)-(Number(a.progress)||0));if(sort==='started')books.sort((a,b)=>dateValue(b,'startedAt')-dateValue(a,'startedAt'));if(sort==='completed-date')books.sort((a,b)=>dateValue(b,'completedAt')-dateValue(a,'completedAt'));const groupLabel=book=>({series:book.series||'No series',author:book.author||'Unknown author',status:book.status||'Unspecified',genre:(book.genres||[])[0]||'No genre',rating:`${formatRatingValue(book.rating)} / 5`,year:String(new Date(book.completedAt||book.startedAt||book.createdAt||0).getFullYear()||'Unknown year'),favorites:book.favorite?'Favorites':'Other',reading:book.status==='reading'?'Currently Reading':'Other',completed:book.status==='completed'?'Completed':'Other'}[prefs.group]||'');const groups=prefs.group==='none'?new Map([['',books]]):books.reduce((map,book)=>{const label=groupLabel(book);if(!map.has(label))map.set(label,[]);map.get(label).push(book);return map;},new Map());list.innerHTML=books.length?[...groups].map(([label,items])=>`${label?`<h3 class="library-group-title">${esc(label)}</h3>`:''}<div class="book-collection" data-library-layout="${prefs.layout}" data-card-size="${prefs.cardSize}">${items.map(book=>bookCard(book,false)).join('')}</div>`).join(''):`<div class="empty-state"><h3>${copy('noBooks')}</h3><button class="primary-button" data-action="add-book">${copy('addBook')}</button></div>`;bindActions(list);};draw();el.querySelector('.library-preferences').ontoggle=event=>{if(!matchMedia('(min-width:651px)').matches)libraryFiltersOpen=event.target.open;event.target.querySelector('summary')?.setAttribute('aria-expanded',String(event.target.open));};search.oninput=()=>{librarySearchQuery=search.value;draw();};[['bookSort','sort'],['bookGroup','group'],['bookGenre','genre'],['bookLayout','layout'],['bookCardSize','cardSize']].forEach(([id,key])=>el.querySelector(`#${id}`).onchange=event=>{prefs[key]=event.target.value;saveState();renderLibrary();});el.querySelectorAll('[data-library-visible]').forEach(input=>input.onchange=()=>{prefs.visible[input.dataset.libraryVisible]=input.checked;saveState();draw();});bindActions(el);}
function bookCardStats(book){return{genres:book.genres||[],aboutSummary:book.summary||book.about||'',notesCount:(book.notes||[]).length,theoryCount:bookLinkedTheories(book).length,dossierCount:bookLinkedDossiers(book).length,wallCount:bookLinkedWalls(book).length};}
function bookCard(b,compact){const renderer=globalThis.VisualBuilder?.renderBookCard;if(globalThis.__VISUAL_DEBUG__)console.debug('[VisualBuilder] app.bookCard',{activeRenderer:renderer?'VisualBuilder.renderBookCard':'app.bookCard fallback',bookId:b.id,templateId:b.visualTemplateId||'',templateMode:renderer?'freeform':'fallback',moduleCount:renderer?globalThis.VisualBuilder.templateForBook(b).modules.length:0,coordinatesUsed:Boolean(renderer),regionsUsed:false,cacheVersion:globalThis.VisualBuilder?.VISUAL_ASSET_VERSION||'runtime-not-loaded'});return renderer?.(b,{compact,presentation:compact?'list':state.libraryPreferences?.layout||'card',size:compact?'small':state.libraryPreferences?.cardSize||'medium',visible:state.libraryPreferences?.visible||freshState().libraryPreferences.visible})||`<article class="book-card visual-card-loading"><div class="book-info"><h4><button class="book-profile-link" data-action="view-book" data-id="${b.id}">${esc(b.title)}</button></h4><p>${esc(b.author||'')}</p></div></article>`;}
function renderSession(){const el=document.getElementById('session');const active=state.books.find(b=>b.status==='reading'&&!b.removedFromLibrary&&!b.archived&&!b.hidden);if(!active){el.innerHTML=`<div class="empty-state"><h3>No active reading assignment</h3><button class="primary-button" data-action="add-book">${copy('addBook')}</button></div>`;bindActions(el);return;}const running=!!state.currentSession;el.innerHTML=`<div class="panel session-card"><p class="eyebrow">${esc(active.title)}</p><h3>Chapter ${esc(active.chapter||'unknown')} · ${active.progress||0}%</h3><div class="timer" id="timerDisplay">${formatTime(running?sessionSeconds:0)}</div><div class="button-row" style="justify-content:center"><button class="primary-button" id="sessionToggle">${running?'End Session':copy('startSession')}</button><button class="secondary-button" data-action="progress-book" data-id="${active.id}">Update Progress</button></div><div class="quick-grid">${['Theory','Suspicion','Important clue','Character update','Quote','Prediction','Dragon','Artifact'].map(x=>`<button class="quick-choice" data-quick="${x}">${x}</button>`).join('')}</div></div>`;el.querySelector('#sessionToggle').addEventListener('click',()=>running?endSession():startSession(active));el.querySelectorAll('[data-quick]').forEach(b=>b.addEventListener('click',()=>openQuickMark(b.dataset.quick,active.id)));bindActions(el);if(running)startTimer();}
function formatTime(s){return [Math.floor(s/3600),Math.floor(s%3600/60),s%60].map(x=>String(x).padStart(2,'0')).join(':');}
function startSession(b){state.currentSession={id:uid(),bookId:b.id,startedAt:Date.now()};saveState();award(2,'Reading session begun.');renderSession();}
function startTimer(){clearInterval(sessionTimer);sessionTimer=setInterval(()=>{if(!state.currentSession)return;sessionSeconds=Math.floor((Date.now()-state.currentSession.startedAt)/1000);const d=document.getElementById('timerDisplay');if(d)d.textContent=formatTime(sessionSeconds);},1000);}
function endSession(){clearInterval(sessionTimer);const d=Math.floor((Date.now()-state.currentSession.startedAt)/1000);state.sessions.push({...state.currentSession,duration:d,endedAt:Date.now()});state.currentSession=null;sessionSeconds=0;saveState();award(Math.max(4,Math.min(30,Math.round(d/900)*4)),'Session recorded.');renderSession();}

function renderTheories(){const el=document.getElementById('theories');el.innerHTML=`<div class="toolbar"><div><p class="eyebrow">Structured intelligence</p><h3>${copy('navTheories')}</h3></div><div class="button-row"><button class="secondary-button" data-action="quick-suspicion">New Suspicion</button><button class="primary-button" data-action="add-theory">${copy('addTheory')}</button></div></div><div class="intel-columns"><section><h3>Theories</h3>${state.theories.slice().reverse().map(theoryCard).join('')||`<div class="empty-state"><p>${copy('noTheories')}</p></div>`}</section><section><h3>Suspicions</h3>${state.suspicions.slice().reverse().map(suspicionCard).join('')||`<div class="empty-state"><p>No suspicions captured yet.</p></div>`}</section></div>`;bindActions(el);}
function theoryCard(t){const b=state.books.find(x=>x.id===t.bookId);return `<article class="theory-card"><h4>${esc(t.statement)}</h4><p>${esc(t.notes||'')}</p><div class="confidence"><small>Confidence ${t.confidence||50}%</small><div class="confidence-bar"><span style="width:${t.confidence||50}%"></span></div></div><div class="theory-meta"><span class="tag">${esc(t.status||'Under investigation')}</span>${b?`<span class="tag">${esc(b.title)}</span>`:''}<button class="small-button" data-action="pin-theory" data-id="${t.id}">Pin to wall</button><button class="small-button" data-action="delete-theory" data-id="${t.id}">Delete</button></div></article>`;}
function suspicionCard(s){const b=state.books.find(x=>x.id===s.bookId);return `<article class="theory-card suspicion-card"><h4>${esc(s.text)}</h4><div class="theory-meta">${b?`<span class="tag">${esc(b.title)}</span>`:''}${s.chapter?`<span class="tag">Ch. ${esc(s.chapter)}</span>`:''}<button class="small-button" data-action="promote-suspicion" data-id="${s.id}">Develop theory</button><button class="small-button" data-action="pin-suspicion" data-id="${s.id}">Pin to wall</button><button class="small-button" data-action="delete-suspicion" data-id="${s.id}">Delete</button></div></article>`;}

function renderWall(){const el=document.getElementById('wall');const wall=activeWall();const cards=state.wallCards.filter(c=>c.wallId===wall.id);const links=state.wallLinks.filter(l=>l.fromWallId===wall.id||l.toWallId===wall.id);el.innerHTML=`<div class="wall-tabs"><div class="wall-tab-scroll">${state.walls.map(w=>`<button class="wall-tab ${w.id===wall.id?'is-active':''}" data-action="switch-wall" data-id="${w.id}">${esc(w.name)}</button>`).join('')}</div><button class="small-button" data-action="new-wall">＋ Wall</button><button class="small-button" data-action="edit-wall">Edit</button></div><div class="wall-toolbar"><div><p class="eyebrow">${esc(wall.description||'Cross-linked evidence board')}</p><strong>${cards.length} cards · ${links.length} linked connections</strong></div><div class="button-row"><button class="primary-button" data-action="add-wall-card">Add Card</button><button class="secondary-button" data-action="create-link">Link Cards</button><button class="secondary-button" data-action="wall-index">Connection Index</button></div></div><div class="wall-board" id="wallBoard"><svg class="wall-lines" id="wallLines" aria-hidden="true"></svg>${cards.length?'':`<div class="wall-empty"><div><h3>This wall is waiting for evidence.</h3><p>Add custom cards, books, suspicions, theories, creatures, or any category you create.</p></div></div>`}${cards.map(wallCardHtml).join('')}</div>`;bindActions(el);enableWallDragging();requestAnimationFrame(drawWallLinks);}
function activeWall(){return state.walls.find(w=>w.id===state.activeWallId)||state.walls[0];}
function wallCardHtml(c){const incoming=state.wallLinks.filter(l=>l.toCardId===c.id).length,outgoing=state.wallLinks.filter(l=>l.fromCardId===c.id).length;return `<article class="wall-card" data-card-id="${c.id}" data-type="${esc(c.category||'Custom')}" style="left:${c.x||30}px;top:${c.y||30}px;--rot:${c.rot||0}deg"><span class="wall-pin"></span><small>${esc(c.category||'Custom')}</small><h4>${esc(c.title)}</h4><p>${esc(c.text||'')}</p><footer><button class="card-link-count" data-action="card-links" data-id="${c.id}">${incoming+outgoing} links</button><button class="card-menu" data-action="edit-wall-card" data-id="${c.id}">•••</button></footer></article>`;}
function enableWallDragging(){const board=document.getElementById('wallBoard');if(!board)return;board.querySelectorAll('.wall-card').forEach(card=>{let drag=false,sx=0,sy=0,ox=0,oy=0;const move=e=>{if(!drag)return;e.preventDefault();const p=e.touches?.[0]||e;const r=board.getBoundingClientRect();const x=Math.max(0,Math.min(r.width-card.offsetWidth,ox+p.clientX-sx));const y=Math.max(0,Math.min(r.height-card.offsetHeight,oy+p.clientY-sy));card.style.left=x+'px';card.style.top=y+'px';const d=state.wallCards.find(c=>c.id===card.dataset.cardId);d.x=x;d.y=y;drawWallLinks();};const up=()=>{if(drag){drag=false;saveState();}document.removeEventListener('mousemove',move);document.removeEventListener('mouseup',up);document.removeEventListener('touchmove',move);document.removeEventListener('touchend',up);};const down=e=>{if(e.target.closest('button'))return;const p=e.touches?.[0]||e;drag=true;sx=p.clientX;sy=p.clientY;ox=parseFloat(card.style.left)||0;oy=parseFloat(card.style.top)||0;document.addEventListener('mousemove',move);document.addEventListener('mouseup',up);document.addEventListener('touchmove',move,{passive:false});document.addEventListener('touchend',up);};card.addEventListener('mousedown',down);card.addEventListener('touchstart',down,{passive:true});});}
function drawWallLinks(){const svg=document.getElementById('wallLines'),board=document.getElementById('wallBoard');if(!svg||!board)return;const wallId=activeWall().id;const visible=new Map([...board.querySelectorAll('.wall-card')].map(e=>[e.dataset.cardId,e]));svg.setAttribute('viewBox',`0 0 ${board.clientWidth} ${board.clientHeight}`);svg.innerHTML=state.wallLinks.filter(l=>l.fromWallId===wallId&&l.toWallId===wallId).map(l=>{const a=visible.get(l.fromCardId),b=visible.get(l.toCardId);if(!a||!b)return'';const x1=a.offsetLeft+a.offsetWidth/2,y1=a.offsetTop+a.offsetHeight/2,x2=b.offsetLeft+b.offsetWidth/2,y2=b.offsetTop+b.offsetHeight/2;return `<g><line x1="${x1}" y1="${y1}" x2="${x2}" y2="${y2}"></line><text x="${(x1+x2)/2}" y="${(y1+y2)/2-6}">${esc(l.type||'linked')}</text></g>`;}).join('');}

function renderProfile(){const p=path(),bond=state.profile.bond&&!state.profile.bond.sealed?state.profile.bond:null;const eventPending=['rider','gryphon'].includes(state.profile.path)&&!state.profile.eventComplete;const creatureLabel=bond?.type==='Dragon'?'Dragon':bond?.type==='Gryphon'?'Gryphon':'Wyvern';document.getElementById('profile').innerHTML=`<div class="profile-layout"><section class="panel identity-card"><div class="identity-sigil">${p.glyph}</div><p class="eyebrow">${p.short}</p><h3>${esc(state.profile.name)}</h3><div class="tag">${currentRank()}</div><p>${state.profile.points.toLocaleString()} ${p.progressName}</p>${bond?`<div class="bond-card">${bond.creatureImage?`<img class="bond-image" src="${bond.creatureImage}" alt="Uploaded image of ${esc(bond.name)}">`:''}<h4>${esc(bond.name)}</h4><p>${esc(bond.color)} ${esc(bond.type)} · ${esc(bond.subtype)}</p>${abilityPresentationHtml(bond,state.profile.path)}<div class="bond-upload-grid"><label class="upload-tile"><span>${bond.creatureImage?'Replace':'Upload'} ${creatureLabel} Image</span><input type="file" accept="image/*" data-bond-upload="creatureImage"></label><label class="upload-tile">${bond.relicImage?`<img src="${bond.relicImage}" alt="Uploaded relic image">`:''}<span>${bond.relicImage?'Replace':'Upload'} Relic Image</span><input type="file" accept="image/*" data-bond-upload="relicImage"></label></div></div>`:eventPending?`<div class="sealed-result"><strong>Assessment sealed</strong><p>Your bond and ${abilityLabelFor(state.profile.path).toLowerCase()} will be revealed after ${p.event}.</p><p><small>${Math.max(0,p.thresholds[2]-state.profile.points).toLocaleString()} ${p.progressName} remain before the event can begin.</small></p>${state.profile.points>=p.thresholds[2]?`<button class="primary-button" data-action="path-event">Begin ${p.event}</button>`:''}</div>`:''}<div class="button-row"><button class="secondary-button" data-action="change-path">Change Path Theme</button><button class="secondary-button" data-action="visual-builder">Visual Builder</button></div></section><section class="panel"><h3>Rank Progression</h3><div class="rank-list">${p.ranks.map((r,i)=>`<div class="rank-row ${i<=state.profile.rankIndex?'is-earned':''}"><span class="rank-dot">${i<=state.profile.rankIndex?'✓':i+1}</span><div><strong>${r}</strong><small>${i===state.profile.rankIndex?'Current rank':i<state.profile.rankIndex?'Earned':`${p.thresholds[i].toLocaleString()} ${p.progressName}`}</small></div></div>`).join('')}</div></section></div>`;const root=document.getElementById('profile');bindActions(root);root.querySelectorAll('[data-bond-upload]').forEach(input=>input.addEventListener('change',async()=>{const file=input.files?.[0];if(!file)return;try{state.profile.bond[input.dataset.bondUpload]=await compressImage(file);saveState();renderProfile();showToast('Bond record image saved locally.');}catch(e){showToast(e.message||'Image could not be saved.');}}));}

function bindActions(root){root.querySelectorAll('[data-action]').forEach(b=>{b.addEventListener('click',e=>{e.stopPropagation();handleAction(b.dataset.action,b.dataset.id);});if(b.getAttribute('role')==='button')b.addEventListener('keydown',e=>{if(e.target!==b||!['Enter',' '].includes(e.key))return;e.preventDefault();e.stopPropagation();handleAction(b.dataset.action,b.dataset.id);});});}
function handleAction(a,id){({
  'add-book':()=>openBookForm(),'start-reading':()=>startReading(id),'edit-reading-session':()=>openReadingSessionEditor(id),'view-book':()=>openBookProfile(id),'edit-book':()=>openBookForm(state.books.find(book=>book.id===id)),'progress-book':()=>openProgressForm(id),'complete-book':()=>completeBook(id),'pin-book':()=>openPinSource('book',id),
  'add-theory':()=>openTheoryForm(),'delete-theory':()=>deleteItem('theories',id),'pin-theory':()=>openPinSource('theory',id),'quick-suspicion':()=>openQuickMark('Suspicion'),'pin-suspicion':()=>openPinSource('suspicion',id),'delete-suspicion':()=>deleteItem('suspicions',id),'promote-suspicion':()=>promoteSuspicion(id),
  'quick-mark':()=>openQuickMark(),'visual-builder':()=>globalThis.VisualBuilder?.open?.(),'view-library':()=>switchView('library'),'add-wall-card':openWallCardForm,'new-wall':openWallForm,'edit-wall':()=>openWallForm(activeWall()),'switch-wall':()=>{state.activeWallId=id;rememberUiLocation();saveState();renderWall();},'create-link':openLinkForm,'wall-index':openConnectionIndex,'card-links':()=>openCardLinks(id),'edit-wall-card':()=>openEditCard(id),'path-event':openPathEvent,'change-path':openPathChange
}[a]||(()=>{}))();}
function deleteItem(k,id){state[k]=state[k].filter(x=>x.id!==id);if(k==='theories'||k==='suspicions'||k==='books'){const type=k==='theories'?'theory':k==='suspicions'?'suspicion':'book';const removed=state.wallCards.filter(c=>c.sourceType===type&&c.sourceId===id).map(c=>c.id);state.wallCards=state.wallCards.filter(c=>!removed.includes(c.id));state.wallLinks=state.wallLinks.filter(l=>!removed.includes(l.fromCardId)&&!removed.includes(l.toCardId));}saveState();renderAll();}

function activeLibraryBooks(){return state.books.filter(book=>!book.removedFromLibrary&&!book.archived&&!book.hidden);}
function normalizeReadingSession(session,index=0){session=session&&typeof session==='object'?session:{};const startedAt=Number(session.startedAt||session.createdAt)||Date.now(),completedAt=Number(session.completedAt||session.endedAt)||0;const kind=String(session.kind||(session.duration!==undefined||session.endedAt?'activity':'reading-cycle'));return{id:String(session.id||`reading-${session.bookId||'unknown'}-${index}`),bookId:String(session.bookId||''),kind,startedAt,completedAt:completedAt||null,status:String(session.status||(kind==='activity'?'logged':completedAt?'completed':'reading')),notes:String(session.notes||''),createdAt:Number(session.createdAt)||startedAt,updatedAt:Number(session.updatedAt)||completedAt||startedAt,...(session.duration!==undefined?{duration:Number(session.duration)||0}:{})};}
function activeReadingSession(bookId){return state.sessions.find(session=>session.bookId===bookId&&session.kind==='reading-cycle'&&!session.completedAt&&session.status==='reading');}
function startReadingSession(store,bookId,now=Date.now(),sessionId=''){const book=store.books.find(item=>item.id===bookId);if(!book)return{session:null,created:false};const existing=store.sessions.find(session=>session.bookId===bookId&&session.kind==='reading-cycle'&&!session.completedAt&&session.status==='reading');if(existing)return{session:existing,created:false};const session=normalizeReadingSession({id:sessionId||`reading-${bookId}-${now}`,bookId,kind:'reading-cycle',startedAt:now,status:'reading',createdAt:now,updatedAt:now});store.sessions.push(session);book.status='reading';book.startedAt=book.startedAt||now;book.updatedAt=now;return{session,created:true};}
function completeReadingSession(store,bookId,now=Date.now()){const book=store.books.find(item=>item.id===bookId);if(!book)return{session:null,completed:false};let session=store.sessions.find(item=>item.bookId===bookId&&item.kind==='reading-cycle'&&!item.completedAt&&item.status==='reading');if(!session){if(book.status==='completed')return{session:null,completed:false};session=normalizeReadingSession({id:`reading-${bookId}-${now}`,bookId,kind:'reading-cycle',startedAt:book.startedAt||now,status:'reading',createdAt:now,updatedAt:now});store.sessions.push(session);}session.completedAt=now;session.status='completed';session.updatedAt=now;book.status='completed';book.progress=100;book.completedAt=now;book.updatedAt=now;return{session,completed:true};}
function updateReadingSession(store,sessionId,changes={}){const session=store.sessions.find(item=>item.id===sessionId);if(!session)return null;Object.assign(session,changes,{updatedAt:Number(changes.updatedAt)||Date.now()});if(session.status==='reading')session.completedAt=null;return session;}
function startReading(bookId){const result=startReadingSession(state,bookId,Date.now(),uid());if(!result.session)return;if(!result.created)return openReadingSessionEditor(result.session.id);saveState();showToast('Reading session started.');renderAll();}
function readingSessionsFor(bookId){return state.sessions.filter(session=>session.bookId===bookId&&session.kind==='reading-cycle').sort((a,b)=>b.startedAt-a.startedAt);}
function localDateTime(value){if(!value)return'';const date=new Date(value),offset=date.getTimezoneOffset()*60000;return new Date(date-offset).toISOString().slice(0,16);}
function openReadingSessionEditor(sessionId){const session=state.sessions.find(item=>item.id===sessionId),book=session&&state.books.find(item=>item.id===session.bookId);if(!session||!book)return;modal(`<article class="reading-session-editor"><p class="eyebrow">${esc(book.title)}</p><h2 id="formModalTitle">Edit Reading Session</h2><label class="form-group"><span class="field-label">Started</span><input class="text-input" id="readingStartedAt" type="datetime-local" value="${localDateTime(session.startedAt)}"></label><label class="form-group"><span class="field-label">Completed</span><input class="text-input" id="readingCompletedAt" type="datetime-local" value="${localDateTime(session.completedAt)}"></label><label class="form-group"><span class="field-label">Status</span><select class="select-input" id="readingStatus">${['reading','paused','completed','dnf'].map(value=>`<option value="${value}" ${session.status===value?'selected':''}>${value}</option>`).join('')}</select></label><label class="form-group"><span class="field-label">Session notes</span><textarea class="text-area" id="readingNotes">${esc(session.notes)}</textarea></label><div class="button-row"><button class="secondary-button" id="cancelReadingSession">Cancel</button><button class="primary-button" id="saveReadingSession">Save Session</button></div></article>`);document.getElementById('cancelReadingSession').onclick=closeModal;document.getElementById('saveReadingSession').onclick=()=>{const started=Date.parse(v('readingStartedAt')),completed=Date.parse(v('readingCompletedAt'));if(!Number.isFinite(started))return showToast('Choose a valid start date.');session.startedAt=started;session.completedAt=Number.isFinite(completed)?completed:null;session.status=v('readingStatus');session.notes=v('readingNotes');session.updatedAt=Date.now();if(session.status==='completed'&&!session.completedAt)session.completedAt=Date.now();if(session.status==='reading')session.completedAt=null;book.status=session.status==='completed'?'completed':session.status;book.updatedAt=Date.now();saveState();closeModal();openBookProfile(book.id);};}
globalThis.ReadingHistory={normalizeReadingSession,startReadingSession,completeReadingSession,updateReadingSession,activeReadingSession,start:startReading,complete:completeBook,sessionsFor:readingSessionsFor,activeLibraryBooks};
function bookRangeField(id,label,value,format,endpoints=''){return `<div class="reaction-control"><div class="range-label-row"><label id="${id}Label" for="${id}">${label}</label><output id="${id}Value" class="range-value" data-range-value-for="${id}">Current value: ${Number(value)||0} / 5</output></div><div class="shared-range-shell"><input class="shared-range" type="range" id="${id}" min="0" max="5" step="0.5" value="${formatRatingValue(value)}" data-range-format="${format}" aria-labelledby="${id}Label" aria-describedby="${id}Value"><output class="range-bubble" data-range-bubble-for="${id}" aria-hidden="true"></output></div>${endpoints?`<div class="range-endpoints" aria-hidden="true"><span>${endpoints.split('|')[0]}</span><span>${endpoints.split('|')[1]}</span></div>`:''}</div>`;}
function bookLinkedDossiers(book){const ids=new Set(book.linkedDossierIds||[]);(state.dossiers||[]).forEach(dossier=>{if((dossier.bookIds||[]).includes(book.id)||dossier.sourceBookId===book.id)ids.add(dossier.id);});return (state.dossiers||[]).filter(dossier=>ids.has(dossier.id));}
function bookLinkedTheories(book){const ids=new Set(book.linkedTheoryIds||[]);state.theories.forEach(theory=>{if(theory.bookId===book.id||(theory.bookIds||[]).includes(book.id))ids.add(theory.id);});return state.theories.filter(theory=>ids.has(theory.id));}
function bookLinkedWalls(book){const ids=new Set(book.linkedWallIds||[]),dossierIds=new Set(bookLinkedDossiers(book).map(dossier=>dossier.id));(state.wallAppearances||[]).forEach(appearance=>{if(dossierIds.has(appearance.dossierId))ids.add(appearance.wallId);});state.wallCards.forEach(card=>{if(card.sourceType==='book'&&card.sourceId===book.id)ids.add(card.wallId);});return state.walls.filter(wall=>ids.has(wall.id));}
function openBookNoteEditor(bookId,noteId=''){const book=state.books.find(item=>item.id===bookId),note=book?.notes.find(item=>item.id===noteId);if(!book)return;modal(`<article class="book-note-editor"><p class="eyebrow">${esc(book.title)}</p><h2 id="formModalTitle">${note?'Edit note':'Add book note'}</h2><label class="form-group"><span class="field-label">Personal note</span><textarea class="text-area" id="bookNoteText">${esc(note?.text||'')}</textarea></label><div class="button-row"><button type="button" class="secondary-button" id="cancelBookNote">Cancel</button><button type="button" class="primary-button" id="saveBookNote">Save Note</button>${note?'<button type="button" class="danger-button" id="deleteBookNote">Delete Note</button>':''}</div></article>`);document.getElementById('cancelBookNote').onclick=()=>openBookProfile(book.id);document.getElementById('saveBookNote').onclick=()=>{const text=v('bookNoteText');if(!text)return showToast('Write a note before saving.');const now=Date.now();if(note){note.text=text;note.updatedAt=now;}else book.notes.push({id:uid(),text,createdAt:now,updatedAt:now});book.updatedAt=now;saveState();openBookProfile(book.id);};if(note)document.getElementById('deleteBookNote').onclick=()=>{if(!confirm('Delete this book note?'))return;book.notes=book.notes.filter(item=>item.id!==note.id);book.updatedAt=Date.now();saveState();openBookProfile(book.id);};}
function openBookConnectionEditor(bookId){const book=state.books.find(item=>item.id===bookId);if(!book)return;modal(`<article class="book-connection-editor"><p class="eyebrow">Book relationship</p><h2 id="formModalTitle">Connect ${esc(book.title)}</h2><label class="form-group"><span class="field-label">Related book</span><select id="bookConnectionTarget" class="select-input"><option value="">Choose a book</option>${state.books.filter(item=>item.id!==book.id).map(item=>`<option value="${item.id}">${esc(item.title)}</option>`).join('')}</select></label><label class="form-group"><span class="field-label">Relationship</span><input id="bookConnectionType" class="text-input" placeholder="sequel to, inspired by, similar to…"></label><label class="form-group"><span class="field-label">Explanation</span><textarea id="bookConnectionExplanation" class="text-area"></textarea></label><label class="form-group"><span class="field-label">Optional notes</span><textarea id="bookConnectionNotes" class="text-area"></textarea></label><div class="button-row"><button type="button" class="secondary-button" id="cancelBookConnection">Cancel</button><button type="button" class="primary-button" id="saveBookConnection">Save Relationship</button></div></article>`);document.getElementById('cancelBookConnection').onclick=()=>openBookProfile(book.id);document.getElementById('saveBookConnection').onclick=()=>{const toBookId=v('bookConnectionTarget'),type=v('bookConnectionType');if(!toBookId||!type)return showToast('Choose a book and relationship.');const duplicate=state.bookConnections.some(item=>item.fromBookId===book.id&&item.toBookId===toBookId&&item.type.toLowerCase()===type.toLowerCase());if(duplicate)return showToast('That book relationship already exists.');state.bookConnections.push({id:uid(),fromBookId:book.id,toBookId,type,explanation:v('bookConnectionExplanation'),notes:v('bookConnectionNotes'),createdAt:Date.now(),updatedAt:Date.now()});saveState();openBookProfile(book.id);};}
function openBookProfile(bookId){const book=state.books.find(item=>item.id===bookId);if(!book)return;normalizeBookRecord(book);const dossiers=bookLinkedDossiers(book),theories=bookLinkedTheories(book),walls=bookLinkedWalls(book),readingHistory=readingSessionsFor(book.id),connections=state.bookConnections.filter(item=>item.fromBookId===book.id||item.toBookId===book.id);modal(`<article class="book-profile"><header>${book.coverUrl?`<img src="${esc(book.coverUrl)}" alt="Cover of ${esc(book.title)}">`:'<span class="book-profile-cover" aria-hidden="true">▤</span>'}<div><p class="eyebrow">Book archive record</p><h2 id="formModalTitle">${esc(book.title)}</h2><p>${esc(book.author||'Unknown author')}${book.series?` · ${esc(book.series)}`:''}</p><div class="book-profile-chips">${book.genres.map(genre=>`<span>${esc(genre)}</span>`).join('')||'<span>No genres</span>'}</div></div><div class="book-profile-header-actions"><button type="button" class="primary-button" id="editBookProfile">Rate & Edit</button><button type="button" class="secondary-button" id="designBookCard">Design Card</button><button type="button" class="secondary-button" id="startBookReading">${activeReadingSession(book.id)?'Current Session':book.status==='completed'?'Start Reread':'Start Reading'}</button></div></header><section><h3>About this book</h3><p>${esc(book.about||'No about section has been written yet.')}</p>${book.summary?`<blockquote>${esc(book.summary)}</blockquote>`:''}</section><section><h3>Ratings</h3><div class="book-profile-metrics"><span>Overall <strong>${formatRatingValue(book.rating)} / 5</strong></span><span>Spice <strong>${formatRatingValue(book.spice)} / 5</strong></span><span>Impact <strong>${formatRatingValue(book.impact)} / 5</strong></span><span>Reaction <strong>${esc(book.reaction)}</strong></span></div></section><details open class="reading-history"><summary>Reading History · ${readingHistory.length}</summary><div class="reading-history-list">${readingHistory.map((session,index)=>`<article class="reading-history-item ${session.completedAt?'is-complete':'is-current'}"><div><small>${session.completedAt?`Read ${readingHistory.length-index}`:'Current session'}</small><strong>${new Date(session.startedAt).toLocaleString()}</strong><span>${session.completedAt?`Completed ${new Date(session.completedAt).toLocaleString()}`:session.status}</span>${session.notes?`<p>${esc(session.notes)}</p>`:''}</div><button type="button" class="secondary-button" data-edit-reading-session="${session.id}">Edit Session</button></article>`).join('')||'<p>No reading sessions recorded yet.</p>'}</div></details><details open class="book-trackers"><summary>Custom Trackers</summary>${globalThis.VisualBuilder?.renderTrackerControls?.(book)||'<p>Design this card to add trackers.</p>'}</details><details open><summary>Connections</summary><div class="book-profile-columns"><section><h4>Dossiers · ${dossiers.length}</h4>${dossiers.map(item=>`<button type="button" data-book-dossier="${item.id}">${esc(item.title)}</button>`).join('')||'<p>No linked dossiers.</p>'}</section><section><h4>Theories · ${theories.length}</h4>${theories.map(item=>`<button type="button" data-book-theory="${item.id}">${esc(item.statement)}</button>`).join('')||'<p>No linked theories.</p>'}</section><section><h4>Walls · ${walls.length}</h4>${walls.map(item=>`<button type="button" data-book-wall="${item.id}">${esc(item.name)}</button>`).join('')||'<p>No linked walls.</p>'}</section><section><h4>Book relationships · ${connections.length}</h4>${connections.map(connection=>{const other=state.books.find(item=>item.id===(connection.fromBookId===book.id?connection.toBookId:connection.fromBookId));return`<article><strong>${esc(connection.type)} · ${esc(other?.title||'Missing book')}</strong><p>${esc(connection.explanation||connection.notes||'No explanation.')}</p></article>`;}).join('')||'<p>No book relationships.</p>'}<button type="button" id="addBookConnection">Add Relationship</button></section></div></details><details open><summary>Notes · ${book.notes.length}</summary><div class="book-profile-notes">${book.notes.map(note=>`<article><p>${esc(note.text)}</p><small>Updated ${new Date(note.updatedAt).toLocaleString()}</small><button type="button" data-edit-book-note="${note.id}">Edit note</button></article>`).join('')||'<p>No personal notes yet.</p>'}</div><button type="button" id="addBookNote">Add Note</button></details>${book.images.length?`<details><summary>Additional images · ${book.images.length}</summary><div class="book-profile-images">${book.images.map(image=>`<figure><img src="${esc(image.url)}" alt="${esc(image.caption||image.type)}"><figcaption>${esc(image.caption||image.type)}</figcaption></figure>`).join('')}</div></details>`:''}<footer><small>Created ${new Date(book.createdAt).toLocaleString()} · Updated ${new Date(book.updatedAt).toLocaleString()}</small></footer></article>`);document.getElementById('formModal').classList.add('book-profile-backdrop');document.getElementById('editBookProfile').onclick=()=>openBookForm(book);document.getElementById('designBookCard').onclick=()=>globalThis.VisualBuilder?.openForBook?.(book.id);document.getElementById('startBookReading').onclick=()=>startReading(book.id);document.querySelectorAll('[data-edit-reading-session]').forEach(button=>button.onclick=()=>openReadingSessionEditor(button.dataset.editReadingSession));document.querySelectorAll('[data-tracker-module]').forEach(input=>input.oninput=()=>globalThis.VisualBuilder?.updateTrackerValue?.(book.id,input.dataset.trackerModule,input.value,{persist:false}));document.querySelectorAll('[data-tracker-module]').forEach(input=>input.onchange=()=>globalThis.VisualBuilder?.updateTrackerValue?.(book.id,input.dataset.trackerModule,input.value,{persist:true}));document.getElementById('addBookNote').onclick=()=>openBookNoteEditor(book.id);document.getElementById('addBookConnection').onclick=()=>openBookConnectionEditor(book.id);document.querySelectorAll('[data-edit-book-note]').forEach(button=>button.onclick=()=>openBookNoteEditor(book.id,button.dataset.editBookNote));document.querySelectorAll('[data-book-dossier]').forEach(button=>button.onclick=()=>globalThis.InfiniteWall?.openDossier(button.dataset.bookDossier));document.querySelectorAll('[data-book-theory]').forEach(button=>button.onclick=()=>{closeModal();handleAction('edit-theory',button.dataset.bookTheory);});document.querySelectorAll('[data-book-wall]').forEach(button=>button.onclick=()=>{state.activeWallId=button.dataset.bookWall;rememberUiLocation();saveState();closeModal();switchView('wall');});}
function removeBookFromLibrary(book){book.removedFromLibrary=true;book.updatedAt=Date.now();saveState();closeModal();renderAll();showToast('Book removed from the visible library. Its archive records were preserved.');}
function deleteBookPermanently(book){if(!confirm(`Permanently delete ${book.title}? Ratings, sessions, theories, notes, wall placements, and linked records will be removed. This cannot be undone.`))return;const theoryIds=new Set(state.theories.filter(item=>item.bookId===book.id).map(item=>item.id)),suspicionIds=new Set(state.suspicions.filter(item=>item.bookId===book.id).map(item=>item.id)),dossierIds=new Set((state.dossiers||[]).filter(d=>(d.sourceType==='book'&&d.sourceId===book.id)||(d.sourceType==='theory'&&theoryIds.has(d.sourceId))||(d.sourceType==='suspicion'&&suspicionIds.has(d.sourceId))).map(d=>d.id));state.books=state.books.filter(item=>item.id!==book.id);state.sessions=state.sessions.filter(item=>item.bookId!==book.id);state.theories=state.theories.filter(item=>item.bookId!==book.id);state.suspicions=state.suspicions.filter(item=>item.bookId!==book.id);state.wallCards=state.wallCards.filter(item=>!((item.sourceType==='book'&&item.sourceId===book.id)||(item.sourceType==='theory'&&theoryIds.has(item.sourceId))||(item.sourceType==='suspicion'&&suspicionIds.has(item.sourceId))));state.wallAppearances=(state.wallAppearances||[]).filter(item=>!dossierIds.has(item.dossierId));state.bookConnections=state.bookConnections.filter(connection=>connection.fromBookId!==book.id&&connection.toBookId!==book.id);state.dossierLinks=(state.dossierLinks||[]).filter(link=>!dossierIds.has(link.fromDossierId)&&!dossierIds.has(link.toDossierId)&&link.sourceBookId!==book.id);state.dossiers=(state.dossiers||[]).filter(d=>!dossierIds.has(d.id));saveState();closeModal();renderAll();showToast('Book permanently deleted.');}
function openBookForm(existing=null){
  const editing=Boolean(existing),book=normalizeBookRecord(existing?JSON.parse(JSON.stringify(existing)):{}),history=editing?readingSessionsFor(existing.id):[];
  const tabButton=(id,label,selected=false)=>`<button type="button" role="tab" id="bookTab-${id}" data-book-editor-tab="${id}" aria-controls="bookPanel-${id}" aria-selected="${selected}">${label}</button>`;
  const panel=(id,html,active=false)=>`<section role="tabpanel" id="bookPanel-${id}" aria-labelledby="bookTab-${id}" data-book-editor-panel="${id}" class="book-editor-panel ${active?'is-active':''}">${html}</section>`;
  const overview=`<div class="book-form-grid"><label class="form-group"><span class="field-label">Title</span><input class="text-input" id="bTitle" value="${esc(book.title||'')}"></label><label class="form-group"><span class="field-label">Author</span><input class="text-input" id="bAuthor" list="bookAuthorSuggestions" autocomplete="off" value="${esc(book.author||'')}"><datalist id="bookAuthorSuggestions">${uniqueBookValues('author').map(value=>`<option value="${esc(value)}"></option>`).join('')}</datalist></label><label class="form-group"><span class="field-label">Series</span><input class="text-input" id="bSeries" list="bookSeriesSuggestions" autocomplete="off" value="${esc(book.series||'')}"><datalist id="bookSeriesSuggestions">${uniqueBookValues('series').map(value=>`<option value="${esc(value)}"></option>`).join('')}</datalist></label><label class="form-group full"><span class="field-label">Genres, comma separated</span><input class="text-input" id="bGenres" value="${esc(book.genres?.join(', ')||'')}" placeholder="Create or reuse any genres"></label><label class="form-group full"><span class="field-label">Tags, comma separated</span><input class="text-input" id="bTags" value="${esc(book.tags?.join(', ')||'')}"></label><label class="form-group full"><span class="field-label">Cover image URL</span><input class="text-input" type="url" id="bCoverUrl" value="${esc(book.coverUrl||'')}"></label><label class="form-group full book-file-field"><span class="field-label">Upload cover</span><input type="file" id="bCoverFile" accept="image/*"><small class="field-help">Choose an image from this device. The existing URL remains unless you enter a new one.</small></label><label class="form-group full"><span class="field-label">Short summary</span><textarea class="text-area" id="bSummary">${esc(book.summary||'')}</textarea></label><label class="form-group full"><span class="field-label">About this book</span><textarea class="text-area" id="bAbout" placeholder="What is this book?">${esc(book.about||'')}</textarea></label><label class="form-group full"><span class="field-label">Additional image URLs, one per line</span><textarea class="text-area" id="bImages">${esc((book.images||[]).map(image=>image.url).join('\n'))}</textarea></label></div>`;
  const reading=`<label class="form-group"><span class="field-label">Current status</span><select class="select-input" id="bStatus">${[['reading','Currently reading'],['want','Want to read'],['paused','Paused'],['completed','Completed'],['dnf','DNF']].map(([value,label])=>`<option value="${value}" ${value===(book.status||'reading')?'selected':''}>${label}</option>`).join('')}</select></label><div class="book-editor-history"><h3>Reading sessions</h3>${history.map(session=>`<article><strong>${new Date(session.startedAt).toLocaleString()}</strong><span>${session.completedAt?`Completed ${new Date(session.completedAt).toLocaleString()}`:esc(session.status)}</span></article>`).join('')||'<p>No reading history yet. Save the book, then start reading from its profile.</p>'}</div>`;
  const ratings=`<fieldset class="book-reactions"><legend>Built-in ratings</legend><div class="reaction-grid">${bookRangeField('bRating','Overall rating',book.rating,'rating')}${bookRangeField('bSpice','Spice rating',book.spice,'spice','None|Maximum Spice')}${bookRangeField('bImpact','Emotional impact',book.impact,'impact','Unshaken|Devastated')}<label class="form-group reaction-select"><span class="field-label">Did you like it?</span><select class="select-input" id="bReaction">${['Not rated','Loved it','Liked it','Mixed feelings','Not for me'].map(value=>`<option ${value===(book.reaction||'Not rated')?'selected':''}>${value}</option>`).join('')}</select></label></div></fieldset><section class="book-editor-trackers"><h3>Custom trackers</h3>${globalThis.VisualBuilder?.renderTrackerControls?.(book)||'<p>Design this card to add custom trackers.</p>'}</section>`;
  const connections=`<div class="book-form-grid"><label class="form-group full"><span class="field-label">Linked dossiers</span><select class="select-input book-link-select" id="bDossiers" multiple size="5">${(state.dossiers||[]).map(item=>`<option value="${item.id}" ${(book.linkedDossierIds||[]).includes(item.id)?'selected':''}>${esc(item.title)}</option>`).join('')}</select></label><label class="form-group full"><span class="field-label">Linked theories</span><select class="select-input book-link-select" id="bTheories" multiple size="5">${state.theories.map(item=>`<option value="${item.id}" ${(book.linkedTheoryIds||[]).includes(item.id)||item.bookId===book.id||(item.bookIds||[]).includes(book.id)?'selected':''}>${esc(item.statement)}</option>`).join('')}</select></label><label class="form-group full"><span class="field-label">Linked walls</span><select class="select-input book-link-select" id="bWalls" multiple size="4">${state.walls.map(item=>`<option value="${item.id}" ${(book.linkedWallIds||[]).includes(item.id)?'selected':''}>${esc(item.name)}</option>`).join('')}</select></label></div><p class="field-help">${editing?state.bookConnections.filter(item=>item.fromBookId===book.id||item.toBookId===book.id).length:0} book relationships. Manage relationship explanations from the Book Profile.</p>`;
  const cardDesign=`<div class="book-card-design-panel"><h3>Assigned visual template</h3><p><strong>${esc(state.visualTemplates.find(template=>template.id===book.visualTemplateId)?.name||'Default Book Card')}</strong></p><p>Use the visual editor to position modules, style trackers, and preview this book. No raw configuration is exposed.</p><button type="button" class="primary-button" id="designBookFromEditor" ${editing?'':'disabled'}>Design Card</button>${editing?'':'<small>Save this book before designing its card.</small>'}</div>`;
  const danger=editing?`<section class="book-delete-zone"><h3>Danger Zone</h3><p>Removing preserves archive records. Permanent deletion destroys linked book data.</p><div><button type="button" class="secondary-button" id="removeBookFromLibrary">Remove From Library</button><button type="button" class="danger-button" id="deleteBookPermanently">Delete Permanently</button></div></section>`:'<p>Danger Zone becomes available after this book is saved.</p>';
  modal(`<div class="book-editor"><header class="book-modal-header"><p class="eyebrow">${editing?'Library record':'New book'}</p><h2 id="formModalTitle">${editing?'Rate & Edit':copy('addBook')}</h2><p>Changes remain a draft until you choose Save.</p></header><nav class="book-editor-tabs" role="tablist" aria-label="Book editor sections">${tabButton('overview','Overview',true)}${tabButton('reading','Reading')}${tabButton('ratings','Ratings & Trackers')}${tabButton('connections','Connections')}${tabButton('card','Card Design')}${tabButton('danger','Danger Zone')}</nav><div class="book-form-body">${panel('overview',overview,true)}${panel('reading',reading)}${panel('ratings',ratings)}${panel('connections',connections)}${panel('card',cardDesign)}${panel('danger',danger)}</div><footer class="book-modal-footer"><button type="button" class="secondary-button" id="cancelBook">Cancel</button><button type="button" class="primary-button" id="saveBook">${editing?'Save Book Details':'Save Book'}</button></footer></div>`);
  const host=document.getElementById('formModal');if(!host)return;host.classList.add('book-modal-backdrop');globalThis.RangeUI?.enhance(document.getElementById('formModalContent'));
  const selectTab=id=>{document.querySelectorAll('[data-book-editor-tab]').forEach(button=>button.setAttribute('aria-selected',String(button.dataset.bookEditorTab===id)));document.querySelectorAll('[data-book-editor-panel]').forEach(section=>section.classList.toggle('is-active',section.dataset.bookEditorPanel===id));};document.querySelectorAll('[data-book-editor-tab]').forEach(button=>button.onclick=()=>selectTab(button.dataset.bookEditorTab));
  document.querySelectorAll('[data-tracker-module]').forEach(input=>input.oninput=()=>{book.trackerValues[input.dataset.trackerModule]=Number(input.value);const output=document.querySelector(`[data-tracker-output="${input.dataset.trackerModule}"]`);if(output)output.value=`${input.value} / ${input.max}`;});
  document.getElementById('cancelBook').onclick=()=>closeModal();if(editing){document.getElementById('removeBookFromLibrary').onclick=()=>removeBookFromLibrary(existing);document.getElementById('deleteBookPermanently').onclick=()=>deleteBookPermanently(existing);document.getElementById('designBookFromEditor').onclick=()=>globalThis.VisualBuilder?.openForBook?.(existing.id);}
  document.getElementById('saveBook').onclick=async()=>{const title=v('bTitle').trim();if(!title)return showToast('Add a book title first.');let coverUrl=v('bCoverUrl')||book.coverUrl||'';const coverFile=document.getElementById('bCoverFile').files?.[0];if(coverFile){try{coverUrl=await compressImage(coverFile);}catch(error){return showToast(error.message||'Cover image could not be saved.');}}const selectedValues=id=>[...document.getElementById(id).selectedOptions].map(option=>option.value),rating=Number(v('bRating')),spice=Number(v('bSpice')),impact=Number(v('bImpact')),reaction=v('bReaction'),data={title,updatedAt:Date.now(),author:v('bAuthor'),series:v('bSeries'),seriesId:(state.series||[]).find(item=>item.name.toLowerCase()===v('bSeries').toLowerCase())?.id||book.seriesId||'',status:v('bStatus'),coverUrl,coverImage:coverUrl,genres:normalizeTextList(v('bGenres')),summary:v('bSummary'),about:v('bAbout'),tags:normalizeTextList(v('bTags')),images:v('bImages').split(/\n+/).map((url,index)=>({id:book.images?.[index]?.id||uid(),type:book.images?.[index]?.type||'additional',url:url.trim(),caption:book.images?.[index]?.caption||''})).filter(image=>image.url),linkedDossierIds:selectedValues('bDossiers'),linkedTheoryIds:selectedValues('bTheories'),linkedWallIds:selectedValues('bWalls'),rating,spice,impact,reaction,ratings:{overall:rating,spice,impact,reaction},metadata:book.metadata||{},visualTemplateId:book.visualTemplateId||'standard-book-card-v1',trackerValues:{...(book.trackerValues||{})}};let savedBook;if(editing){Object.assign(existing,data);savedBook=existing;}else{savedBook={id:uid(),createdAt:Date.now(),...data,notes:[],progress:data.status==='completed'?100:0,chapter:''};state.books.push(savedBook);}state.theories.forEach(theory=>{theory.bookIds=[...new Set([...(theory.bookIds||[]).filter(id=>id!==savedBook.id),...(savedBook.linkedTheoryIds.includes(theory.id)?[savedBook.id]:[])])];});(state.dossiers||[]).forEach(dossier=>{dossier.bookIds=[...new Set([...(dossier.bookIds||[]).filter(id=>id!==savedBook.id),...(savedBook.linkedDossierIds.includes(dossier.id)?[savedBook.id]:[])])];});normalizeBookRecord(savedBook);saveState();closeModal();if(!editing)award(5,'Book added.');else showToast('Book details saved.');renderAll();};
}
function openProgressForm(id){const b=state.books.find(x=>x.id===id);if(!b)return;modal(`<p class="eyebrow">${esc(b.title)}</p><h2 id="formModalTitle">Update Progress</h2><label class="form-group"><span class="field-label">Progress percent</span><input type="range" min="0" max="100" class="shared-range" data-range-format="percent" id="progressValue" value="${b.progress||0}"></label><label class="form-group"><span class="field-label">Current chapter</span><input class="text-input" id="chapterValue" value="${esc(b.chapter||'')}"></label><button class="primary-button full-width" id="saveProgress">Save</button>`);document.getElementById('saveProgress').onclick=()=>{const old=b.progress||0;b.progress=Math.max(0,Math.min(100,Number(v('progressValue'))||0));b.chapter=v('chapterValue');if(b.progress>0&&b.status==='want')b.status='reading';saveState();closeModal();award(Math.max(1,Math.round(Math.max(0,b.progress-old)/5)),'Progress secured.');renderAll();};}
function completeBook(id){const result=completeReadingSession(state,id);if(!result.completed)return showToast('This reading is already complete.');saveState();award(120,copy('completeBook'));renderAll();}
function openTheoryForm(prefill='',bookId=''){modal(`<p class="eyebrow">Theory ledger</p><h2 id="formModalTitle">${copy('addTheory')}</h2><label class="form-group"><span class="field-label">Theory statement</span><textarea class="text-area" id="tStatement">${esc(prefill)}</textarea></label><label class="form-group"><span class="field-label">Source book</span><select class="select-input" id="tBook"><option value="">No book</option>${bookOptions(bookId)}</select></label><div class="form-grid"><label class="form-group"><span class="field-label">Confidence</span><input class="shared-range" type="range" data-range-format="percent" id="tConfidence" min="0" max="100" value="50"></label><label class="form-group"><span class="field-label">Status</span><select class="select-input" id="tStatus">${['Fleeting suspicion','Under investigation','Strong possibility','Nearly certain','Confirmed','Partially confirmed','Disproven','Technically correct, catastrophically misunderstood'].map(x=>`<option>${x}</option>`).join('')}</select></label></div><label class="form-group"><span class="field-label">Reasoning and evidence</span><textarea class="text-area" id="tNotes"></textarea></label><button class="primary-button full-width" id="saveTheory">${copy('saveTheory')}</button>`);document.getElementById('saveTheory').onclick=()=>{const statement=v('tStatement');if(!statement)return;state.theories.push({id:uid(),statement,bookId:v('tBook'),confidence:Number(v('tConfidence')),status:v('tStatus'),notes:v('tNotes'),createdAt:Date.now()});saveState();closeModal();award(12,copy('success'));renderAll();};}
function openQuickMark(type='Suspicion',bookId=''){modal(`<p class="eyebrow">Quick Mark · ${esc(type)}</p><h2 id="formModalTitle">Capture it before it disappears</h2><label class="form-group"><span class="field-label">What did you notice?</span><textarea class="text-area" id="quickText"></textarea></label><label class="form-group"><span class="field-label">Source book</span><select class="select-input" id="quickBook"><option value="">No book</option>${bookOptions(bookId||state.books.find(b=>b.status==='reading')?.id)}</select></label><label class="form-group"><span class="field-label">Chapter or location</span><input class="text-input" id="quickChapter"></label><label class="form-check"><input type="checkbox" id="quickPin"><span>Pin to a conspiracy wall now</span></label><button class="primary-button full-width" id="saveQuick">Save Quick Mark</button>`);document.getElementById('saveQuick').onclick=()=>{const text=v('quickText');if(!text)return;const item={id:uid(),text,bookId:v('quickBook'),chapter:v('quickChapter'),type,createdAt:Date.now()};if(type==='Theory'){closeModal();return openTheoryForm(text,item.bookId);}state.suspicions.push(item);saveState();if(document.getElementById('quickPin').checked){closeModal();openPinSource('suspicion',item.id);}else{closeModal();award(4,'Suspicion secured.');renderAll();}};}
function promoteSuspicion(id){const s=state.suspicions.find(x=>x.id===id);if(s)openTheoryForm(s.text,s.bookId);}
function bookOptions(selected=''){return state.books.map(b=>`<option value="${b.id}" ${b.id===selected?'selected':''}>${esc(b.title)}</option>`).join('');}

function openWallForm(existing=null){modal(`<p class="eyebrow">Wall management</p><h2 id="formModalTitle">${existing?'Edit':'Create'} Wall</h2><label class="form-group"><span class="field-label">Wall name</span><input class="text-input" id="wName" value="${esc(existing?.name||'')}"></label><label class="form-group"><span class="field-label">Purpose</span><textarea class="text-area" id="wDesc">${esc(existing?.description||'')}</textarea></label><label class="form-group"><span class="field-label">Card categories, comma separated</span><textarea class="text-area" id="wCats">${esc((existing?.categories||activeWall().categories).join(', '))}</textarea></label><button class="primary-button full-width" id="saveWall">Save Wall</button>`);document.getElementById('saveWall').onclick=()=>{const name=v('wName');if(!name)return;const data={name,description:v('wDesc'),categories:v('wCats').split(',').map(x=>x.trim()).filter(Boolean)};if(existing)Object.assign(existing,data);else{const w={id:uid(),...data};state.walls.push(w);state.activeWallId=w.id;}saveState();closeModal();renderWall();};}
function openWallCardForm(){const w=activeWall();modal(`<p class="eyebrow">${esc(w.name)}</p><h2 id="formModalTitle">Add a Card</h2><div class="form-grid"><label class="form-group"><span class="field-label">Category</span><select class="select-input" id="cCategory">${w.categories.map(x=>`<option>${esc(x)}</option>`).join('')}<option value="__new">Create new category…</option></select></label><label class="form-group"><span class="field-label">New category</span><input class="text-input" id="cNewCategory" placeholder="Only if creating one"></label><label class="form-group full"><span class="field-label">Title</span><input class="text-input" id="cTitle"></label><label class="form-group full"><span class="field-label">Details</span><textarea class="text-area" id="cText"></textarea></label><button class="primary-button full" id="saveCard">Pin Card</button></div>`);document.getElementById('saveCard').onclick=()=>{let category=v('cCategory');if(category==='__new'){category=v('cNewCategory');if(category&&!w.categories.includes(category))w.categories.push(category);}const title=v('cTitle');if(!title||!category)return;state.wallCards.push({id:uid(),wallId:w.id,category,title,text:v('cText'),sourceType:'custom',x:30+Math.random()*320,y:40+Math.random()*280,rot:Math.random()*3-1.5});saveState();closeModal();renderWall();};}
function sourceData(type,id){if(type==='book'){const x=state.books.find(b=>b.id===id);return x&&{title:x.title,text:`${x.author||'Unknown author'}${x.series?' · '+x.series:''}`,category:'Book'};}if(type==='theory'){const x=state.theories.find(t=>t.id===id);return x&&{title:'Theory',text:x.statement,category:'Theory'};}if(type==='suspicion'){const x=state.suspicions.find(s=>s.id===id);return x&&{title:'Suspicion',text:x.text,category:'Suspicion'};}return null;}
function openPinSource(type,id){const src=sourceData(type,id);if(!src)return;modal(`<p class="eyebrow">Pin linked source</p><h2 id="formModalTitle">Choose a wall</h2><p><strong>${esc(src.title)}</strong><br>${esc(src.text)}</p><label class="form-group"><span class="field-label">Destination wall</span><select class="select-input" id="pinWall">${state.walls.map(w=>`<option value="${w.id}">${esc(w.name)}</option>`).join('')}</select></label><label class="form-group"><span class="field-label">Card category</span><input class="text-input" id="pinCategory" value="${src.category}"></label><button class="primary-button full-width" id="doPin">Pin to Wall</button>`);document.getElementById('doPin').onclick=()=>{const wallId=v('pinWall');if(!state.wallCards.some(c=>c.wallId===wallId&&c.sourceType===type&&c.sourceId===id))state.wallCards.push({id:uid(),wallId,category:v('pinCategory')||src.category,title:src.title,text:src.text,sourceType:type,sourceId:id,x:40+Math.random()*300,y:50+Math.random()*280,rot:Math.random()*3-1.5});state.activeWallId=wallId;saveState();closeModal();switchView('wall');};}
function allCardOptions(selected=''){return state.walls.flatMap(w=>state.wallCards.filter(c=>c.wallId===w.id).map(c=>`<option value="${c.id}" ${c.id===selected?'selected':''}>${esc(w.name)} › ${esc(c.category)} › ${esc(c.title)}</option>`)).join('');}
function openLinkForm(prefill=''){if(state.wallCards.length<2)return showToast('Add at least two cards before linking them.');modal(`<p class="eyebrow">Cross-wall connection</p><h2 id="formModalTitle">Link Cards</h2><label class="form-group"><span class="field-label">From</span><select class="select-input" id="lFrom">${allCardOptions(prefill)}</select></label><label class="form-group"><span class="field-label">Relationship</span><input class="text-input" id="lType" list="linkTypes" placeholder="supports, contradicts, knows…"><datalist id="linkTypes"><option>supports</option><option>contradicts</option><option>conceals</option><option>betrayed</option><option>related to</option><option>present during</option><option>possessed</option><option>possible identity</option><option>caused</option><option>unknown connection</option></datalist></label><label class="form-group"><span class="field-label">To</span><select class="select-input" id="lTo">${allCardOptions()}</select></label><label class="form-group"><span class="field-label">Why are they linked?</span><textarea class="text-area" id="lReason" placeholder="Record the evidence, logic, contradiction, or suspicion behind this connection."></textarea></label><button class="primary-button full-width" id="saveLink">Create Connection</button>`);document.getElementById('saveLink').onclick=()=>{const from=v('lFrom'),to=v('lTo');if(!from||!to||from===to)return showToast('Choose two different cards.');const a=state.wallCards.find(c=>c.id===from),b=state.wallCards.find(c=>c.id===to);state.wallLinks.push({id:uid(),fromCardId:from,toCardId:to,fromWallId:a.wallId,toWallId:b.wallId,type:v('lType')||'linked to',reason:v('lReason'),createdAt:Date.now()});saveState();closeModal();renderWall();};}
function openCardLinks(id){const c=state.wallCards.find(x=>x.id===id);const links=state.wallLinks.filter(l=>l.fromCardId===id||l.toCardId===id);modal(`<p class="eyebrow">Connection record</p><h2 id="formModalTitle">${esc(c.title)}</h2>${links.length?links.map(l=>{const other=state.wallCards.find(x=>x.id===(l.fromCardId===id?l.toCardId:l.fromCardId));const w=state.walls.find(x=>x.id===other?.wallId);return `<article class="link-record"><strong>${l.fromCardId===id?'→':'←'} ${esc(l.type)} ${esc(other?.title||'Missing card')}</strong><small>${esc(w?.name||'Unknown wall')}</small><p>${esc(l.reason||'No reason recorded.')}</p><button class="small-button" data-delete-link="${l.id}">Delete link</button></article>`;}).join(''):`<p>No connections yet.</p>`}<button class="primary-button full-width" id="linkFromCard">Link this card</button>`);document.getElementById('linkFromCard').onclick=()=>{closeModal();openLinkForm(id);};document.querySelectorAll('[data-delete-link]').forEach(b=>b.onclick=()=>{state.wallLinks=state.wallLinks.filter(l=>l.id!==b.dataset.deleteLink);saveState();closeModal();renderWall();});}
function openConnectionIndex(){const rows=state.wallLinks.map(l=>{const a=state.wallCards.find(c=>c.id===l.fromCardId),b=state.wallCards.find(c=>c.id===l.toCardId),wa=state.walls.find(w=>w.id===l.fromWallId),wb=state.walls.find(w=>w.id===l.toWallId);return `<article class="link-record"><strong>${esc(a?.title||'Missing')} <span>→ ${esc(l.type)} →</span> ${esc(b?.title||'Missing')}</strong><small>${esc(wa?.name||'')} to ${esc(wb?.name||'')}</small><p>${esc(l.reason||'No reason recorded.')}</p></article>`;}).join('');modal(`<p class="eyebrow">Global connection index</p><h2 id="formModalTitle">Every Link Across Every Wall</h2><div class="connection-index">${rows||'<p>No connections have been recorded.</p>'}</div>`);}
function openEditCard(id){const c=state.wallCards.find(x=>x.id===id);modal(`<p class="eyebrow">Edit card</p><h2 id="formModalTitle">${esc(c.title)}</h2><label class="form-group"><span class="field-label">Category</span><input class="text-input" id="ecCategory" value="${esc(c.category)}"></label><label class="form-group"><span class="field-label">Title</span><input class="text-input" id="ecTitle" value="${esc(c.title)}"></label><label class="form-group"><span class="field-label">Details</span><textarea class="text-area" id="ecText">${esc(c.text||'')}</textarea></label><div class="button-row"><button class="primary-button" id="saveEditCard">Save</button><button class="secondary-button" id="deleteCard">Delete Card</button></div>`);document.getElementById('saveEditCard').onclick=()=>{c.category=v('ecCategory');c.title=v('ecTitle');c.text=v('ecText');saveState();closeModal();renderWall();};document.getElementById('deleteCard').onclick=()=>{state.wallCards=state.wallCards.filter(x=>x.id!==id);state.wallLinks=state.wallLinks.filter(l=>l.fromCardId!==id&&l.toCardId!==id);saveState();closeModal();renderWall();};}

function openPathEvent(){
  const p=path();
  if(!['rider','gryphon'].includes(state.profile.path)||state.profile.eventComplete)return showToast(`${p.event} has already been completed.`);
  if(state.profile.points<p.thresholds[2])return showToast(`You need ${(p.thresholds[2]-state.profile.points).toLocaleString()} more ${p.progressName} before ${p.event}.`);
  if(!state.profile.assessment)return showToast('Your sealed assessment is missing. Change paths and complete onboarding again.');
  if(!state.profile.bond)state.profile.bond={...generateBondResult(state.profile.path,state.profile.assessment),sealed:true};
  const rider=state.profile.path==='rider';
  modal(`<p class="eyebrow">${p.event}</p><h2 id="formModalTitle">${rider?'Survive the field. Be chosen.':'Step from the edge and trust the bond.'}</h2><p>${rider?'Threshing is not a promotion ceremony. It is the point at which a cadet either leaves the field bonded, or does not leave it at all.':'The Leap asks for trust, conviction, and the courage to step forward without certainty.'}</p><div class="event-trials">${(rider?['Cross the parapet','Identify three threats from incomplete evidence','Choose who you protect when retreat is impossible','Face the field without knowing who will choose you']:['Complete the ascent','State the truth you would defy authority to protect','Choose trust over certainty','Take the leap']).map((x,i)=>`<label class="form-check"><input type="checkbox" class="event-check"><span>${i+1}. ${x}</span></label>`).join('')}</div><button type="button" class="primary-button full-width" id="completeEvent">Complete ${p.event}</button>`);
  const button=document.getElementById('completeEvent');
  button.addEventListener('click',()=>{
    const eventModal=document.getElementById('formModal');const checks=[...eventModal.querySelectorAll('.event-check')];
    if(!checks.length||checks.some(x=>!x.checked))return showToast('Complete every stage of the event.');
    state.profile.eventComplete=true;
    state.profile.bond.sealed=false;
    state.profile.rankIndex=2;
    state.profile.points=Math.max(state.profile.points,p.thresholds[2]);
    state.profile.pendingBondReveal=true;
    state.profile.bondRevealSeen=false;
    saveState();
    closeModal();
    renderAll();
    requestAnimationFrame(()=>setTimeout(showBondingRevealModal,40));
  });
}

function showBondingRevealModal(){
  const b=state.profile.bond,p=path();
  if(!b||b.sealed)return;
  const rider=state.profile.path==='rider';
  const title=rider?'You survived Threshing.':'You completed The Leap.';
  const bondedWord=rider?'Dragon Rider':'Bonded Flier';
  modal(`<div class="bond-reveal-modal"><div class="result-sigil">${p.glyph}</div><p class="eyebrow">Bond confirmed</p><h2 id="formModalTitle">${title}</h2><p class="bond-announcement">You are now a <strong>${bondedWord}</strong>. You are bonded to:</p><h3>${esc(b.name)}</h3><p><strong>${esc(b.color)} ${esc(b.type)}</strong> · ${esc(b.subtype)}</p><p>${esc(b.description||'')}</p>${abilityPresentationHtml(b,state.profile.path)}<div class="reveal-relic"><small>Your relic</small><strong>${esc(b.relic)}</strong></div><p class="muted-copy">You can optionally upload an image of your ${b.type.toLowerCase()} and your relic from your Service Record. Creature names are unique across dragons, gryphons, and wyverns.</p><button type="button" class="primary-button full-width" id="acceptBondReveal">Enter as ${bondedWord}</button></div>`);
  document.getElementById('acceptBondReveal').addEventListener('click',()=>{state.profile.pendingBondReveal=false;state.profile.bondRevealSeen=true;saveState();closeModal();renderAll();showToast(`You are now ${p.ranks[2]}.`);});
}

function compressImage(file){return new Promise((resolve,reject)=>{if(!file.type.startsWith('image/'))return reject(new Error('Choose an image file.'));if(file.size>12*1024*1024)return reject(new Error('Choose an image smaller than 12 MB.'));const reader=new FileReader();reader.onerror=()=>reject(new Error('Image could not be read.'));reader.onload=()=>{const img=new Image();img.onerror=()=>reject(new Error('Image could not be opened.'));img.onload=()=>{const max=1200,scale=Math.min(1,max/Math.max(img.width,img.height));const canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(img.width*scale));canvas.height=Math.max(1,Math.round(img.height*scale));canvas.getContext('2d').drawImage(img,0,0,canvas.width,canvas.height);resolve(canvas.toDataURL('image/jpeg',.82));};img.src=reader.result;};reader.readAsDataURL(file);});}

function openPathChange(){persistActivePathRecord();modal(`<p class="eyebrow">Theme assignment</p><h2 id="formModalTitle">Change Path</h2><p>Every path keeps its own permanent service record. Returning to a previous path restores the exact rank, standing, assessment, event history, creature, path ability, relic, and uploaded images you had before.</p><div class="path-grid">${Object.entries(PATHS).map(([k,p])=>{const saved=state.pathRecords?.[k];const subtitle=saved?(saved.bond&&!saved.bond.sealed?`${saved.bond.name} · ${saved.bond.ability}`:`Saved at ${p.ranks[saved.rankIndex||0]}`):'New path record';return `<button class="path-choice" data-new-path="${k}"><span style="font-size:30px">${p.glyph}</span><strong>${p.name}</strong><small>${esc(subtitle)}</small></button>`;}).join('')}</div>`);document.querySelectorAll('[data-new-path]').forEach(b=>b.onclick=()=>{const next=b.dataset.newPath;if(next===state.profile.path)return closeModal();persistActivePathRecord();const existed=restorePathRecord(next);saveState();closeModal();applyTheme();renderAll();if(!existed&&['rider','gryphon','dark'].includes(next)){selectedPath=next;renderQuestionnaire();setOnboardingStep(2);openModal('onboardingModal');}else if(state.profile.pendingBondReveal&&state.profile.bond&&!state.profile.bond.sealed){setTimeout(showBondingRevealModal,50);}else{showToast(existed?`${PATHS[next].name} record restored.`:`${PATHS[next].name} path opened.`);}});}

function modal(html){const content=document.getElementById('formModalContent');if(!content)return false;content.innerHTML=html;return openModal();}
function v(id){return document.getElementById(id)?.value?.trim?.()??document.getElementById(id)?.value??'';}

if(!globalThis.__ABILITY_TEST__)init();
